175: /// Classify a DJI `.txt` log version into its architectural and cryptographic capabilities.
176: ///
177: /// # Invariants
178: /// - Versions 1 through 6: 1-byte length width, no scrambling, details at EOF.
179: /// - Versions 7 through 11: 2-byte length width, cyclic XOR scrambling, details at EOF.
180: /// - Version 12: 2-byte length width, cyclic XOR scrambling, details relocated to header offset.
181: /// - Versions 13 through 14: 2-byte length width, AES encryption, details at header offset.
182: /// - All other versions: rejected with [`FlightReaderError::UnsupportedVersion`].
183: ///
184: /// # Errors
185: /// Returns [`FlightReaderError::UnsupportedVersion`] if `version` is not in `1..=14`.
186: pub fn classify_version(version: u8) -> Result<VersionCapabilities, FlightReaderError> {
187:     match version {
188:         1..=6 => Ok(VersionCapabilities {
