//! DJI `.txt` flight log record stream demuxer and envelope parser.
//!
//! Provides zero-allocation framing and streaming parsing for DJI `.txt` telemetry records
//! across format versions 1 through 14. Supports variable-length field decoding (1 byte for v1–v6,
//! 2 bytes Little-Endian for v7–v14), delimiter (`0xFF`) validation, automatic XOR de-scrambling
//! routing, FeaturePoint 8 plaintext bypass, and resilient stream resynchronization.

use std::borrow::Cow;
use std::ops::Deref;

use byteorder::{ByteOrder, LittleEndian};

use crate::crypto::xor;
use crate::error::{FlightReaderError, Result};
use crate::txt::header::TxtHeader;
use crate::txt::version::{classify_version, DetailsLocation, ScrambleType, VersionCapabilities};

/// Framing delimiter sentinel byte separating consecutive records (`0xFF` / `255` decimal).
pub const RECORD_DELIMITER: u8 = 0xFF;

/// A zero-allocation borrowed view of a raw DJI `.txt` flight telemetry record envelope.
///
/// Encapsulates the record type identifier and borrowed payload slice directly
/// referencing the memory-mapped or buffered flight log byte stream.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RawRecordEnvelope<'a> {
    /// Numerical record type identifier (e.g. 1 for OSD, 2 for Home, 56 for KeyStorage).
    pub record_type: u8,
    /// Borrowed raw payload slice directly referencing the stream buffer.
    ///
    /// - For v1–v6: unencrypted plaintext telemetry payload.
    /// - For v7–v12: raw scrambled payload starting with the seed byte (`payload[0]`).
    /// - For v13–v14: raw envelope payload (or plaintext bypass for FeaturePoint 8).
    pub payload: &'a [u8],
}

impl<'a> RawRecordEnvelope<'a> {
    /// Constructs a new `RawRecordEnvelope` from borrowed fields.
    #[inline]
    pub const fn new(record_type: u8, payload: &'a [u8]) -> Self {
        Self {
            record_type,
            payload,
        }
    }

    /// Parses a single record envelope from the beginning of `input`.
    ///
    /// # Protocol Wire Format
    /// - Byte 0: `record_type` (`u8`)
    /// - Bytes 1..=W: `length` (`u8` if `record_len_width == 1`, `u16_le` if `record_len_width == 2`)
    /// - Bytes (1+W)..((1+W)+L): `payload` (`L` bytes)
    /// - Byte (1+W)+L: Delimiter byte (must equal `0xFF`)
    ///
    /// Returns `Ok((envelope, total_consumed_bytes))`.
    ///
    /// # Errors
    /// - [`FlightReaderError::UnexpectedEof`] if `input.len()` cannot hold the record header.
    /// - [`FlightReaderError::TruncatedRecord`] if `input.len()` is less than the full wire size.
    /// - [`FlightReaderError::InvalidRecordDelimiter`] if the byte following the payload is not `0xFF`.
    /// - [`FlightReaderError::UnsupportedVersion`] if `record_len_width` is not 1 or 2.
    pub fn parse(input: &'a [u8], record_len_width: usize) -> Result<(Self, usize)> {
        let header_size = 1 + record_len_width;
        if input.len() < header_size {
            return Err(FlightReaderError::UnexpectedEof);
        }

        let record_type = input[0];
        let payload_len = match record_len_width {
            1 => input[1] as usize,
            2 => LittleEndian::read_u16(&input[1..3]) as usize,
            other => {
                return Err(FlightReaderError::UnsupportedVersion {
                    version: other as u8,
                });
            }
        };

        let total_len = header_size + payload_len + 1;
        if input.len() < total_len {
            return Err(FlightReaderError::TruncatedRecord {
                expected: total_len,
                available: input.len(),
            });
        }

        let delimiter = input[header_size + payload_len];
        if delimiter != RECORD_DELIMITER {
            return Err(FlightReaderError::InvalidRecordDelimiter { found: delimiter });
        }

        let payload = &input[header_size..header_size + payload_len];
        Ok((Self { record_type, payload }, total_len))
    }

    /// De-scrambles or passes through the record payload into a caller-provided destination slice.
    ///
    /// # Behavior by Version
    /// - **v1–v6** (`ScrambleType::None`): Plaintext copy into `out_buf`.
    /// - **v7–v12** (`ScrambleType::Xor`): De-scrambles `payload[1..]` into `out_buf` using
    ///   ECMA-182 CRC64 keystream derived from `(record_type, payload[0])`.
    /// - **v13–v14** (`ScrambleType::Aes`): Yields raw envelope payload into `out_buf`
    ///   (plaintext bypass for FeaturePoint 8: `KeyStorage` 56, `FlightRecordRecover` 50).
    ///
    /// # Errors
    /// - [`FlightReaderError::BufferOverflow`] if `out_buf` capacity is insufficient.
    /// - [`FlightReaderError::PayloadTooShort`] if XOR scrambled payload length is `< 2` (requires seed + data).
    /// - [`FlightReaderError::UnsupportedVersion`] if `version` is not supported.
    pub fn decode_into<'b>(&self, version: u8, out_buf: &'b mut [u8]) -> Result<&'b [u8]> {
        let caps = classify_version(version)?;
        match caps.scramble_type {
            ScrambleType::None => {
                if out_buf.len() < self.payload.len() {
                    return Err(FlightReaderError::BufferOverflow {
                        required: self.payload.len(),
                        capacity: out_buf.len(),
                    });
                }
                out_buf[..self.payload.len()].copy_from_slice(self.payload);
                Ok(&out_buf[..self.payload.len()])
            }
            ScrambleType::Xor => {
                if self.payload.is_empty() {
                    return Ok(&[]);
                }
                if self.payload.len() < 2 {
                    return Err(FlightReaderError::PayloadTooShort {
                        minimum: 2,
                        available: self.payload.len(),
                    });
                }
                let plaintext_len = self.payload.len() - 1;
                if out_buf.len() < plaintext_len {
                    return Err(FlightReaderError::BufferOverflow {
                        required: plaintext_len,
                        capacity: out_buf.len(),
                    });
                }
                let seed = self.payload[0];
                let key = xor::derive_key(self.record_type, seed);
                xor::descramble_slice(&self.payload[1..], &mut out_buf[..plaintext_len], key)?;
                Ok(&out_buf[..plaintext_len])
            }
            ScrambleType::Aes => {
                if out_buf.len() < self.payload.len() {
                    return Err(FlightReaderError::BufferOverflow {
                        required: self.payload.len(),
                        capacity: out_buf.len(),
                    });
                }
                out_buf[..self.payload.len()].copy_from_slice(self.payload);
                Ok(&out_buf[..self.payload.len()])
            }
        }
    }

    /// Automatically routes and decodes payload according to log format version capabilities.
    ///
    /// - **v1–v6**: Returns `RecordPayload::Borrowed` containing zero-copy plaintext payload slice.
    /// - **v7–v12**: Returns `RecordPayload::Owned` containing XOR de-scrambled bytes.
    /// - **v13–v14**: Returns `RecordPayload::Borrowed` containing raw envelope payload
    ///   (FeaturePoint 8 records 56 and 50 are plaintext bypass).
    ///
    /// # Errors
    /// - [`FlightReaderError::PayloadTooShort`] if XOR scrambled payload length is `< 2`.
    /// - [`FlightReaderError::UnsupportedVersion`] if `version` is not supported (1..=14).
    pub fn decode_payload(&self, version: u8) -> Result<RecordPayload<'a>> {
        let caps = classify_version(version)?;
        match caps.scramble_type {
            ScrambleType::None => Ok(RecordPayload::Borrowed(self.payload)),
            ScrambleType::Xor => {
                if self.payload.is_empty() {
                    return Ok(RecordPayload::Borrowed(&[]));
                }
                if self.payload.len() < 2 {
                    return Err(FlightReaderError::PayloadTooShort {
                        minimum: 2,
                        available: self.payload.len(),
                    });
                }
                let descrambled = xor::descramble_record_to_vec(self.payload, self.record_type)?;
                Ok(RecordPayload::Owned(descrambled))
            }
            ScrambleType::Aes => {
                // FeaturePoint 8 plaintext bypass (KeyStorage 56, FlightRecordRecover 50)
                // and raw envelope yield for Milestone 3 AES decryption.
                Ok(RecordPayload::Borrowed(self.payload))
            }
        }
    }

    /// De-scrambles this record payload using the cyclic XOR keystream engine.
    ///
    /// Expects `self.payload[0]` to be the seed byte and `self.payload[1..]` to be
    /// ciphertext.
    ///
    /// # Errors
    /// Returns [`FlightReaderError::PayloadTooShort`] if `self.payload.len() < 2`.
    pub fn descramble_xor(&self) -> Result<Vec<u8>> {
        xor::descramble_record_to_vec(self.payload, self.record_type)
    }

    /// Returns `true` if this record is a FeaturePoint 8 plaintext bypass record (50 or 56).
    #[inline]
    pub const fn is_plaintext_bypass(&self) -> bool {
        self.record_type == 56 || self.record_type == 50
    }
}

/// A decoded or pass-through telemetry payload slice, providing zero-allocation access where possible.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RecordPayload<'a> {
    /// Zero-copy borrowed slice directly referencing the stream buffer (v1–v6 or raw envelopes).
    Borrowed(&'a [u8]),
    /// Owned vector holding de-scrambled bytes (v7–v12).
    Owned(Vec<u8>),
}

impl<'a> RecordPayload<'a> {
    /// Returns the payload as a borrowed byte slice.
    #[inline]
    pub fn as_slice(&self) -> &[u8] {
        match self {
            Self::Borrowed(s) => s,
            Self::Owned(v) => v.as_slice(),
        }
    }

    /// Converts this payload into an owned [`Vec<u8>`].
    #[inline]
    pub fn to_vec(&self) -> Vec<u8> {
        match self {
            Self::Borrowed(s) => s.to_vec(),
            Self::Owned(v) => v.clone(),
        }
    }

    /// Returns `true` if the payload is borrowed without heap allocation.
    #[inline]
    pub const fn is_borrowed(&self) -> bool {
        matches!(self, Self::Borrowed(_))
    }

    /// Returns `true` if the payload is an owned allocated buffer.
    #[inline]
    pub const fn is_owned(&self) -> bool {
        matches!(self, Self::Owned(_))
    }
}

impl<'a> Deref for RecordPayload<'a> {
    type Target = [u8];

    #[inline]
    fn deref(&self) -> &Self::Target {
        self.as_slice()
    }
}

impl<'a> AsRef<[u8]> for RecordPayload<'a> {
    #[inline]
    fn as_ref(&self) -> &[u8] {
        self.as_slice()
    }
}

impl<'a> From<&'a [u8]> for RecordPayload<'a> {
    #[inline]
    fn from(s: &'a [u8]) -> Self {
        Self::Borrowed(s)
    }
}

impl<'a> From<Vec<u8>> for RecordPayload<'a> {
    #[inline]
    fn from(v: Vec<u8>) -> Self {
        Self::Owned(v)
    }
}

impl<'a> From<RecordPayload<'a>> for Cow<'a, [u8]> {
    #[inline]
    fn from(p: RecordPayload<'a>) -> Self {
        match p {
            RecordPayload::Borrowed(s) => Cow::Borrowed(s),
            RecordPayload::Owned(v) => Cow::Owned(v),
        }
    }
}

/// Maps a format version and numerical record type identifier to its FeaturePoint ID.
///
/// Returns FeaturePoint domain identifier (1..=14), or 0 for unencrypted auxiliary types.
/// FeaturePoint 8 designates plaintext bypass (`KeyStorage` 56, `FlightRecordRecover` 50).
#[must_use]
pub fn get_feature_point(version: u8, record_type: u8) -> u8 {
    if version == 13 {
        match record_type {
            50 | 56 => 8, // PlainText_8 bypass
            42 | 57 => 0, // Unencrypted
            5 | 9 | 10 | 20 | 24 | 30 | 54 => 7, // DJIFlyCustom_7
            12 | 16 | 19 | 22 | 26 | 27 | 28 | 51 | 52 | 55 => 6, // AfterSales_6
            49 => 5, // AirLink_5
            21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
            31 | 32 | 34 | 35 | 36 | 38 | 39 => 3, // Waypoint_3
            17 | 18 => 2, // Vision_2
            53 => 9, // FlightHub_9
            _ => 1, // Base_1
        }
    } else {
        // Version 14 (Granular domain isolation)
        match record_type {
            50 | 55 | 56 | 209 | 218 | 226 => 8, // PlainText_8 bypass
            42 => 0, // Unencrypted
            3 => 10, // Gimbal_10
            4 | 11 | 29 | 33 | 62 => 11, // RC_11
            25 => 12, // Camera_12
            7 | 8 | 22 => 13, // Battery_13
            28 | 51 | 52 => 14, // FlySafe_14
            5 | 9 | 10 | 20 | 24 | 30 | 54 | 253 | 254 => 7, // DJIFlyCustom_7
            12 | 16 | 19 | 26 | 27 => 6, // AfterSales_6
            49 | 57 => 5, // AirLink_5
            21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
            31 | 32 | 34 | 35 | 36 | 38 | 39 | 60 => 3, // Waypoint_3
            17 | 18 | 61 => 2, // Vision_2
            53 => 9, // FlightHub_9
            _ => 1, // Base_1
        }
    }
}

/// Streaming zero-allocation iterator over DJI `.txt` binary flight records.
///
/// Tracks stream byte offsets, version capabilities, and details summary partitions
/// to demux sequential telemetry envelopes until reaching stream boundary or EOF.
#[derive(Debug, Clone)]
pub struct RecordEnvelopeIterator<'a> {
    buffer: &'a [u8],
    current_offset: usize,
    end_offset: usize,
    capabilities: VersionCapabilities,
    header_offset: usize,
    resync: bool,
}

impl<'a> RecordEnvelopeIterator<'a> {
    /// Constructs a new `RecordEnvelopeIterator` from a flight log buffer and parsed header.
    ///
    /// # Stream Boundary Resolution
    /// - **v1–v11** (`DetailsLocation::EndOfFile`): Telemetry records reside from `header_length`
    ///   (100 bytes) up to `details_offset`.
    /// - **v12–v14** (`DetailsLocation::HeaderOffset`): Summary details reside between `header_length`
    ///   and `details_offset`, and telemetry records begin at `details_offset` running to EOF (`buffer.len()`).
    ///
    /// # Errors
    /// Returns [`FlightReaderError::CorruptedHeader`] if `details_offset` is negative.
    /// Returns [`FlightReaderError::UnsupportedVersion`] if header version is unhandled.
    pub fn new(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
        let capabilities = header.capabilities()?;
        let header_offset = header.header_length as usize;

        let (current_offset, end_offset) = match capabilities.details_location {
            DetailsLocation::EndOfFile => {
                let end = if header.details_offset >= 0 {
                    (header.details_offset as usize).min(buffer.len())
                } else {
                    return Err(FlightReaderError::CorruptedHeader);
                };
                let start = header_offset.min(end);
                (start, end)
            }
            DetailsLocation::HeaderOffset => {
                let start = if header.details_offset >= 0 {
                    (header.details_offset as usize).min(buffer.len())
                } else {
                    return Err(FlightReaderError::CorruptedHeader);
                };
                (start, buffer.len())
            }
        };

        Ok(Self {
            buffer,
            current_offset,
            end_offset,
            capabilities,
            header_offset,
            resync: true,
        })
    }

    /// Alias for [`Self::new`] for explicit naming.
    #[inline]
    pub fn from_header(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
        Self::new(buffer, header)
    }

    /// Constructs an iterator over a raw record slice with known version capabilities.
    #[inline]
    pub fn from_slice(slice: &'a [u8], capabilities: VersionCapabilities) -> Self {
        Self {
            buffer: slice,
            current_offset: 0,
            end_offset: slice.len(),
            capabilities,
            header_offset: 0,
            resync: true,
        }
    }

    /// Configures whether resilient stream resynchronization is enabled.
    ///
    /// In resilient mode (`resync: true`, default), corrupted delimiters or framing errors
    /// advance forward byte-by-byte (`cursor += 1`) to search for the next valid record boundary
    /// without panicking or terminating early.
    #[inline]
    pub fn with_resync(mut self, resync: bool) -> Self {
        self.resync = resync;
        self
    }

    /// Returns whether resilient stream resynchronization is currently enabled.
    #[inline]
    pub const fn resync(&self) -> bool {
        self.resync
    }

    /// Current cursor offset within the input `buffer`.
    #[inline]
    pub const fn current_offset(&self) -> usize {
        self.current_offset
    }

    /// Synonym for [`Self::current_offset`].
    #[inline]
    pub const fn cursor(&self) -> usize {
        self.current_offset
    }

    /// End boundary offset bounding this record stream.
    #[inline]
    pub const fn end_offset(&self) -> usize {
        self.end_offset
    }

    /// Header boundary offset where records began.
    #[inline]
    pub const fn header_offset(&self) -> usize {
        self.header_offset
    }

    /// Version capabilities governing this record stream.
    #[inline]
    pub const fn capabilities(&self) -> &VersionCapabilities {
        &self.capabilities
    }

    /// Returns unconsumed slice of the record stream partition.
    #[inline]
    pub fn remaining(&self) -> &'a [u8] {
        if self.current_offset >= self.end_offset || self.current_offset >= self.buffer.len() {
            &[]
        } else {
            &self.buffer[self.current_offset..self.end_offset.min(self.buffer.len())]
        }
    }
}

impl<'a> Iterator for RecordEnvelopeIterator<'a> {
    type Item = Result<RawRecordEnvelope<'a>>;

    fn next(&mut self) -> Option<Self::Item> {
        let record_len_width = self.capabilities.record_len_width;
        let header_size = 1 + record_len_width;

        while self.current_offset < self.end_offset {
            // In resilient mode, skip stray delimiters between records
            if self.resync && self.buffer[self.current_offset] == RECORD_DELIMITER {
                self.current_offset += 1;
                continue;
            }

            // Check if remaining slice can hold at least a record header
            let remaining = self.end_offset - self.current_offset;
            if remaining < header_size {
                // Trailing padding bytes before EOF or Details block
                self.current_offset = self.end_offset;
                return None;
            }

            let slice = &self.buffer[self.current_offset..self.end_offset];
            match RawRecordEnvelope::parse(slice, record_len_width) {
                Ok((envelope, total_len)) => {
                    self.current_offset += total_len;
                    return Some(Ok(envelope));
                }
                Err(err) => {
                    if !self.resync {
                        // Strict mode: advance cursor so caller can inspect or abort
                        self.current_offset = match err {
                            FlightReaderError::InvalidRecordDelimiter { .. } => {
                                self.current_offset + 1
                            }
                            _ => self.end_offset,
                        };
                        return Some(Err(err));
                    }

                    // Resilient mode: scan forward byte-by-byte (cursor += 1)
                    self.current_offset += 1;
                }
            }
        }

        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_raw_envelope_parse_v1_v6() {
        // [type 1, len 4, payload 10 20 30 40, delimiter 0xFF]
        let wire = [0x01, 0x04, 0x10, 0x20, 0x30, 0x40, 0xFF];
        let (env, total_len) = RawRecordEnvelope::parse(&wire, 1).unwrap();
        assert_eq!(total_len, 7);
        assert_eq!(env.record_type, 1);
        assert_eq!(env.payload, &[0x10, 0x20, 0x30, 0x40]);

        // decode_payload returns borrowed
        let payload = env.decode_payload(3).unwrap();
        assert!(payload.is_borrowed());
        assert_eq!(&*payload, &[0x10, 0x20, 0x30, 0x40]);

        // decode_into
        let mut out = [0u8; 4];
        let decoded = env.decode_into(3, &mut out).unwrap();
        assert_eq!(decoded, &[0x10, 0x20, 0x30, 0x40]);
    }

    #[test]
    fn test_raw_envelope_parse_v7_v12_xor() {
        // OSD Record Type 1, seed 0x42
        // Wire: [type 0x01, len 11 0x0B 0x00, seed 0x42, ciphertext 10B, delimiter 0xFF]
        let wire = [
            0x01, 0x0B, 0x00, 0x42, 0xE1, 0x9C, 0x96, 0x85, 0xFB, 0x3B, 0x06, 0x31, 0xE9, 0x94,
            0xFF,
        ];
        let (env, total_len) = RawRecordEnvelope::parse(&wire, 2).unwrap();
        assert_eq!(total_len, 15);
        assert_eq!(env.record_type, 1);

        let payload = env.decode_payload(8).unwrap();
        assert!(payload.is_owned());
        assert_eq!(
            &*payload,
            &[0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A]
        );

        let mut out = [0u8; 10];
        let decoded = env.decode_into(8, &mut out).unwrap();
        assert_eq!(
            decoded,
            &[0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A]
        );
    }

    #[test]
    fn test_raw_envelope_parse_v13_v14_plaintext_bypass() {
        // KeyStorage Type 56
        let mut wire = vec![56, 16, 0];
        wire.extend_from_slice(&[0x5A; 16]);
        wire.push(0xFF);

        let (env, total_len) = RawRecordEnvelope::parse(&wire, 2).unwrap();
        assert_eq!(total_len, 20);
        assert_eq!(env.record_type, 56);
        assert!(env.is_plaintext_bypass());

        let payload = env.decode_payload(13).unwrap();
        assert!(payload.is_borrowed());
        assert_eq!(&*payload, &[0x5A; 16]);

        let mut out = [0u8; 16];
        let decoded = env.decode_into(13, &mut out).unwrap();
        assert_eq!(decoded, &[0x5A; 16]);
    }

    #[test]
    fn test_corrupted_delimiter_strict_vs_resilient() {
        // Wire with bad delimiter 0x00 instead of 0xFF
        let wire = [0x01, 0x02, 0xAA, 0xBB, 0x00];
        let caps = classify_version(3).unwrap();

        // Strict mode: emits error
        let mut strict_iter = RecordEnvelopeIterator::from_slice(&wire, caps).with_resync(false);
        let res = strict_iter.next().unwrap();
        assert_eq!(
            res,
            Err(FlightReaderError::InvalidRecordDelimiter { found: 0x00 })
        );

        // Resilient mode: scans forward byte-by-byte and cleanly finishes without panic
        let mut resync_iter = RecordEnvelopeIterator::from_slice(&wire, caps).with_resync(true);
        assert!(resync_iter.next().is_none());
    }

    #[test]
    fn test_zero_length_payload() {
        // v1-v6 zero length: [0x01, 0x00, 0xFF]
        let wire_v1 = [0x01, 0x00, 0xFF];
        let (env_v1, len_v1) = RawRecordEnvelope::parse(&wire_v1, 1).unwrap();
        assert_eq!(len_v1, 3);
        assert_eq!(env_v1.payload, &[]);
        let p_v1 = env_v1.decode_payload(1).unwrap();
        assert_eq!(&*p_v1, &[]);

        // v7-v14 zero length: [0x01, 0x00, 0x00, 0xFF]
        let wire_v7 = [0x01, 0x00, 0x00, 0xFF];
        let (env_v7, len_v7) = RawRecordEnvelope::parse(&wire_v7, 2).unwrap();
        assert_eq!(len_v7, 4);
        assert_eq!(env_v7.payload, &[]);
        let p_v7 = env_v7.decode_payload(8).unwrap();
        assert_eq!(&*p_v7, &[]);
    }

    #[test]
    fn test_resilient_recovery_across_noise() {
        // 2 noise bytes, followed by valid record 1, corrupted delimiter, valid record 2
        let mut stream = vec![0xEE, 0xEE]; // Noise
        stream.extend_from_slice(&[0x01, 0x02, 0x11, 0x22, 0xFF]); // Valid rec 1 (len 2)
        stream.extend_from_slice(&[0x02, 0x01, 0x33, 0x00]); // Corrupted delimiter 0x00
        stream.extend_from_slice(&[0x04, 0x01, 0x44, 0xFF]); // Valid rec 2 (len 1)

        let caps = classify_version(1).unwrap();
        let mut iter = RecordEnvelopeIterator::from_slice(&stream, caps).with_resync(true);

        let r1 = iter.next().unwrap().unwrap();
        assert_eq!(r1.record_type, 1);
        assert_eq!(r1.payload, &[0x11, 0x22]);

        let r2 = iter.next().unwrap().unwrap();
        assert_eq!(r2.record_type, 4);
        assert_eq!(r2.payload, &[0x44]);

        assert!(iter.next().is_none());
    }

    #[test]
    fn test_buffer_overflow_error_decode_into() {
        let wire = [0x01, 0x04, 0x10, 0x20, 0x30, 0x40, 0xFF];
        let (env, _) = RawRecordEnvelope::parse(&wire, 1).unwrap();
        let mut small_out = [0u8; 3]; // Need 4 bytes
        let err = env.decode_into(3, &mut small_out).unwrap_err();
        assert_eq!(
            err,
            FlightReaderError::BufferOverflow {
                required: 4,
                capacity: 3
            }
        );
    }

    #[test]
    fn test_get_feature_point_authoritative() {
        assert_eq!(get_feature_point(13, 56), 8);
        assert_eq!(get_feature_point(13, 50), 8);
        assert_eq!(get_feature_point(13, 42), 0);
        assert_eq!(get_feature_point(13, 1), 1);
        assert_eq!(get_feature_point(14, 56), 8);
        assert_eq!(get_feature_point(14, 50), 8);
        assert_eq!(get_feature_point(14, 3), 10);
        assert_eq!(get_feature_point(14, 4), 11);
    }
}

