//! Comprehensive integration tests for DJI `.txt` record stream demuxer and envelope parser.
//!
//! Tests cover:
//! - Synthetic v1–v6 legacy plaintext logs
//! - Synthetic v7–v12 cyclic XOR scrambled logs
//! - Synthetic v13–v14 modern logs with FeaturePoint 8 plaintext bypass
//! - Delimiter corruption and resilient stream resynchronization
//! - Truncated headers, lengths, and payloads
//! - Empty streams and zero-length payloads
//! - Trailing padding byte tolerances
//! - Zero-allocation `decode_into` scratch buffer operations
//! - Proptest property-based fuzz invariants

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::crypto::derive_key;
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::header::TxtHeader;
use flightreader_core::txt::record::{
    get_feature_point, RawRecordEnvelope, RecordEnvelopeIterator, RecordPayload, RECORD_DELIMITER,
};
use flightreader_core::txt::version::classify_version;
use proptest::prelude::*;

/// Helper to build a standard 100-byte synthetic TxtHeader.
fn create_test_header(version: u8, header_len: i16, details_offset: i64) -> Vec<u8> {
    let mut buf = vec![0u8; header_len as usize];
    LittleEndian::write_i64(&mut buf[0..8], details_offset);
    LittleEndian::write_i16(&mut buf[8..10], header_len);
    buf[10] = version;
    buf[11] = 2; // DjiGo
    buf[12] = if version >= 7 { 1 } else { 0 }; // scrambled flag
    buf
}

#[test]
fn test_synthetic_v1_to_v6_plaintext_demux() {
    for version in 1..=6 {
        let mut file_buf = create_test_header(version, 100, 1000);
        let header = TxtHeader::parse(&file_buf).expect("Valid header");

        // Record 1: OSD (Type 1), length 5, payload [1, 2, 3, 4, 5], delimiter 0xFF
        file_buf.extend_from_slice(&[0x01, 0x05, 0x01, 0x02, 0x03, 0x04, 0x05, RECORD_DELIMITER]);
        // Record 2: Home (Type 2), length 3, payload [10, 20, 30], delimiter 0xFF
        file_buf.extend_from_slice(&[0x02, 0x03, 0x0A, 0x14, 0x1E, RECORD_DELIMITER]);
        // Record 3: Gimbal (Type 3), length 2, payload [99, 100], delimiter 0xFF
        file_buf.extend_from_slice(&[0x03, 0x02, 0x63, 0x64, RECORD_DELIMITER]);

        // Fix details_offset in header to match exactly the end of records
        let details_offset = file_buf.len() as i64;
        LittleEndian::write_i64(&mut file_buf[0..8], details_offset);

        // Add 50 bytes of Details Summary data after details_offset (should NOT be parsed as records)
        file_buf.extend_from_slice(&[0x77; 50]);

        let parsed_header = TxtHeader::parse(&file_buf).unwrap();
        let mut iter = RecordEnvelopeIterator::new(&file_buf, &parsed_header).unwrap();

        assert_eq!(iter.header_offset(), 100);
        assert_eq!(iter.current_offset(), 100);
        assert_eq!(iter.end_offset(), details_offset as usize);

        // Rec 1
        let r1 = iter.next().unwrap().expect("Rec 1 must parse");
        assert_eq!(r1.record_type, 1);
        assert_eq!(r1.payload, &[1, 2, 3, 4, 5]);
        let p1 = r1.decode_payload(version).unwrap();
        assert!(p1.is_borrowed());
        assert_eq!(&*p1, &[1, 2, 3, 4, 5]);

        // Rec 2
        let r2 = iter.next().unwrap().expect("Rec 2 must parse");
        assert_eq!(r2.record_type, 2);
        assert_eq!(r2.payload, &[10, 20, 30]);
        let p2 = r2.decode_payload(version).unwrap();
        assert!(p2.is_borrowed());
        assert_eq!(&*p2, &[10, 20, 30]);

        // Rec 3
        let r3 = iter.next().unwrap().expect("Rec 3 must parse");
        assert_eq!(r3.record_type, 3);
        assert_eq!(r3.payload, &[99, 100]);
        let p3 = r3.decode_payload(version).unwrap();
        assert!(p3.is_borrowed());
        assert_eq!(&*p3, &[99, 100]);

        // Iterator must stop at details_offset and NOT parse the 0x77 details bytes
        assert!(iter.next().is_none());
        assert_eq!(iter.current_offset(), details_offset as usize);
    }
}

#[test]
fn test_synthetic_v7_to_v12_xor_scrambled_demux() {
    for version in [7, 8, 9, 10, 11, 12] {
        let is_v12 = version == 12;
        let mut file_buf = if is_v12 {
            // In v12, details block is at 100..150, records start at 150..EOF
            let mut h = create_test_header(version, 100, 150);
            h.extend_from_slice(&[0x99; 50]); // 50 bytes details summary
            h
        } else {
            create_test_header(version, 100, 1000)
        };

        let records_start_offset = file_buf.len();

        // Vector 1: OSD Type 1, seed 42 (0x2A), 10 bytes plaintext [1..=10]
        // Key for (1, 42) is [0x5D, 0x73, 0x0A, 0x59, 0x50, 0xF5, 0x13, 0x01]
        let osd_plaintext = [1u8, 2, 3, 4, 5, 6, 7, 8, 9, 10];
        let osd_key = derive_key(1, 42);
        let mut osd_scrambled = vec![42u8]; // seed
        for (i, &b) in osd_plaintext.iter().enumerate() {
            osd_scrambled.push(b ^ osd_key[i % 8]);
        }
        let osd_wire_len = osd_scrambled.len() as u16; // 11
        file_buf.push(1); // record_type
        file_buf.extend_from_slice(&osd_wire_len.to_le_bytes());
        file_buf.extend_from_slice(&osd_scrambled);
        file_buf.push(RECORD_DELIMITER);

        // Vector 2: Home Type 2, seed 100 (0x64), 6 bytes plaintext [11..=16]
        let home_plaintext = [11u8, 12, 13, 14, 15, 16];
        let home_key = derive_key(2, 100);
        let mut home_scrambled = vec![100u8]; // seed
        for (i, &b) in home_plaintext.iter().enumerate() {
            home_scrambled.push(b ^ home_key[i % 8]);
        }
        let home_wire_len = home_scrambled.len() as u16; // 7
        file_buf.push(2); // record_type
        file_buf.extend_from_slice(&home_wire_len.to_le_bytes());
        file_buf.extend_from_slice(&home_scrambled);
        file_buf.push(RECORD_DELIMITER);

        // Vector 3: RC Type 4, seed 255 (0xFF), 8 bytes plaintext [20..=27]
        let rc_plaintext = [20u8, 21, 22, 23, 24, 25, 26, 27];
        let rc_key = derive_key(4, 255);
        let mut rc_scrambled = vec![255u8]; // seed
        for (i, &b) in rc_plaintext.iter().enumerate() {
            rc_scrambled.push(b ^ rc_key[i % 8]);
        }
        let rc_wire_len = rc_scrambled.len() as u16; // 9
        file_buf.push(4); // record_type
        file_buf.extend_from_slice(&rc_wire_len.to_le_bytes());
        file_buf.extend_from_slice(&rc_scrambled);
        file_buf.push(RECORD_DELIMITER);

        if !is_v12 {
            // For v7–v11, set details_offset to the end of records
            let details_offset = file_buf.len() as i64;
            LittleEndian::write_i64(&mut file_buf[0..8], details_offset);
            // Append Details block bytes
            file_buf.extend_from_slice(&[0x44; 64]);
        }

        let parsed_header = TxtHeader::parse(&file_buf).unwrap();
        let mut iter = RecordEnvelopeIterator::new(&file_buf, &parsed_header).unwrap();

        assert_eq!(iter.current_offset(), records_start_offset);

        // Record 1: OSD
        let r1 = iter.next().unwrap().expect("OSD record parsed");
        assert_eq!(r1.record_type, 1);
        let p1 = r1.decode_payload(version).unwrap();
        assert!(p1.is_owned());
        assert_eq!(&*p1, &osd_plaintext);

        // Record 2: Home
        let r2 = iter.next().unwrap().expect("Home record parsed");
        assert_eq!(r2.record_type, 2);
        let p2 = r2.decode_payload(version).unwrap();
        assert!(p2.is_owned());
        assert_eq!(&*p2, &home_plaintext);

        // Record 3: RC
        let r3 = iter.next().unwrap().expect("RC record parsed");
        assert_eq!(r3.record_type, 4);
        let p3 = r3.decode_payload(version).unwrap();
        assert!(p3.is_owned());
        assert_eq!(&*p3, &rc_plaintext);

        // Concludes cleanly
        assert!(iter.next().is_none());
    }
}

#[test]
fn test_synthetic_v13_v14_raw_envelope_and_plaintext_bypass() {
    for version in [13, 14] {
        // In v13/v14: details at 100..120, records at 120..EOF
        let mut file_buf = create_test_header(version, 100, 120);
        file_buf.extend_from_slice(&[0xAA; 20]); // details summary block

        let start_offset = file_buf.len(); // 120

        // Record 1: KeyStorage (Type 56, FeaturePoint 8 plaintext bypass)
        let key_storage_payload = [0x5A; 16];
        file_buf.push(56);
        file_buf.extend_from_slice(&(key_storage_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&key_storage_payload);
        file_buf.push(RECORD_DELIMITER);

        // Record 2: FlightRecordRecover (Type 50, FeaturePoint 8 plaintext bypass)
        let recover_payload = [0x3C; 8];
        file_buf.push(50);
        file_buf.extend_from_slice(&(recover_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&recover_payload);
        file_buf.push(RECORD_DELIMITER);

        // Record 3: General OSD (Type 1, yields raw envelope)
        let osd_raw_payload = [0x01, 0x02, 0x03, 0x04];
        file_buf.push(1);
        file_buf.extend_from_slice(&(osd_raw_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&osd_raw_payload);
        file_buf.push(RECORD_DELIMITER);

        let parsed_header = TxtHeader::parse(&file_buf).unwrap();
        let mut iter = RecordEnvelopeIterator::new(&file_buf, &parsed_header).unwrap();
        assert_eq!(iter.current_offset(), start_offset);

        // Rec 1: KeyStorage
        let r1 = iter.next().unwrap().unwrap();
        assert_eq!(r1.record_type, 56);
        assert!(r1.is_plaintext_bypass());
        assert_eq!(get_feature_point(version, 56), 8);
        let p1 = r1.decode_payload(version).unwrap();
        assert!(p1.is_borrowed());
        assert_eq!(&*p1, &key_storage_payload);

        // Rec 2: FlightRecordRecover
        let r2 = iter.next().unwrap().unwrap();
        assert_eq!(r2.record_type, 50);
        assert!(r2.is_plaintext_bypass());
        assert_eq!(get_feature_point(version, 50), 8);
        let p2 = r2.decode_payload(version).unwrap();
        assert!(p2.is_borrowed());
        assert_eq!(&*p2, &recover_payload);

        // Rec 3: General OSD (yields raw envelope)
        let r3 = iter.next().unwrap().unwrap();
        assert_eq!(r3.record_type, 1);
        assert!(!r3.is_plaintext_bypass());
        assert_eq!(get_feature_point(version, 1), 1);
        let p3 = r3.decode_payload(version).unwrap();
        assert!(p3.is_borrowed());
        assert_eq!(&*p3, &osd_raw_payload);

        assert!(iter.next().is_none());
    }
}

#[test]
fn test_corrupted_delimiter_resilient_resynchronization() {
    // Construct a slice with:
    // 1. Valid record 1 (Type 1, len 2, payload [0x11, 0x22], 0xFF)
    // 2. Corrupted record with bad delimiter 0x00 instead of 0xFF
    // 3. Noise byte 0xAA
    // 4. Valid record 2 (Type 4, len 1, payload [0x33], 0xFF)
    let mut stream = vec![];
    // Record 1
    stream.extend_from_slice(&[0x01, 0x02, 0x11, 0x22, RECORD_DELIMITER]);
    // Corrupted record
    stream.extend_from_slice(&[0x02, 0x03, 0xAA, 0xBB, 0xCC, 0x00]); // Delimiter 0x00
    // Noise byte
    stream.push(0xDE);
    // Record 2
    stream.extend_from_slice(&[0x04, 0x01, 0x33, RECORD_DELIMITER]);

    let caps = classify_version(1).unwrap();

    // 1. Test resilient mode: recovers Record 1 and Record 2
    let mut resilient_iter = RecordEnvelopeIterator::from_slice(&stream, caps).with_resync(true);
    let r1 = resilient_iter.next().unwrap().expect("Rec 1 must succeed");
    assert_eq!(r1.record_type, 1);
    assert_eq!(r1.payload, &[0x11, 0x22]);

    let r2 = resilient_iter.next().unwrap().expect("Rec 2 must succeed");
    assert_eq!(r2.record_type, 4);
    assert_eq!(r2.payload, &[0x33]);

    assert!(resilient_iter.next().is_none());

    // 2. Test strict mode: returns InvalidRecordDelimiter error on the corrupted record
    let mut strict_iter = RecordEnvelopeIterator::from_slice(&stream, caps).with_resync(false);
    let s1 = strict_iter.next().unwrap().unwrap();
    assert_eq!(s1.record_type, 1);

    let s2 = strict_iter.next().unwrap();
    assert_eq!(
        s2,
        Err(FlightReaderError::InvalidRecordDelimiter { found: 0x00 })
    );
}

#[test]
fn test_truncated_length_and_truncated_payload() {
    let caps_v1 = classify_version(1).unwrap(); // 1-byte length
    let caps_v7 = classify_version(7).unwrap(); // 2-byte length

    // 1. Truncated header: only 1 byte in v7 (needs 3 bytes for type + u16_le len)
    let trunc_hdr = [0x01];
    let mut iter1 = RecordEnvelopeIterator::from_slice(&trunc_hdr, caps_v7).with_resync(false);
    assert!(iter1.next().is_none()); // < header_size is treated as trailing padding

    // 2. Parse method on truncated slice gives UnexpectedEof
    assert_eq!(
        RawRecordEnvelope::parse(&trunc_hdr, 2).unwrap_err(),
        FlightReaderError::UnexpectedEof
    );

    // 3. Truncated payload: declared len 10, only 4 bytes available before EOF
    let trunc_payload = [0x01, 0x0A, 0x11, 0x22, 0x33, 0x44];
    assert_eq!(
        RawRecordEnvelope::parse(&trunc_payload, 1).unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 1 + 1 + 10 + 1, // 13
            available: 6,
        }
    );

    let mut iter2 = RecordEnvelopeIterator::from_slice(&trunc_payload, caps_v1).with_resync(false);
    assert_eq!(
        iter2.next().unwrap().unwrap_err(),
        FlightReaderError::TruncatedRecord {
            expected: 13,
            available: 6,
        }
    );
}

#[test]
fn test_empty_stream_and_zero_length_payload() {
    // 1. Empty buffer
    let empty: [u8; 0] = [];
    let caps = classify_version(1).unwrap();
    let mut iter = RecordEnvelopeIterator::from_slice(&empty, caps);
    assert!(iter.next().is_none());
    assert_eq!(iter.remaining(), &[]);

    // 2. Empty stream via header (details_offset == header_length)
    let hdr_buf = create_test_header(1, 100, 100);
    let header = TxtHeader::parse(&hdr_buf).unwrap();
    let mut hdr_iter = RecordEnvelopeIterator::new(&hdr_buf, &header).unwrap();
    assert_eq!(hdr_iter.current_offset(), 100);
    assert_eq!(hdr_iter.end_offset(), 100);
    assert!(hdr_iter.next().is_none());

    // 3. Zero-length payload record in v1-v6: [type, 0x00, 0xFF]
    let zero_v1 = [0x05, 0x00, RECORD_DELIMITER];
    let (env_v1, total_v1) = RawRecordEnvelope::parse(&zero_v1, 1).unwrap();
    assert_eq!(total_v1, 3);
    assert_eq!(env_v1.record_type, 5);
    assert!(env_v1.payload.is_empty());
    let p_v1 = env_v1.decode_payload(1).unwrap();
    assert!(p_v1.is_empty());

    // 4. Zero-length payload record in v7-v14: [type, 0x00, 0x00, 0xFF]
    let zero_v7 = [0x05, 0x00, 0x00, RECORD_DELIMITER];
    let (env_v7, total_v7) = RawRecordEnvelope::parse(&zero_v7, 2).unwrap();
    assert_eq!(total_v7, 4);
    assert_eq!(env_v7.record_type, 5);
    assert!(env_v7.payload.is_empty());
    let p_v7 = env_v7.decode_payload(8).unwrap();
    assert!(p_v7.is_empty());

    // 5. Length 1 in v7-v12 (seed only, missing ciphertext) -> PayloadTooShort on decode
    let seed_only = [0x01, 0x01, 0x00, 0x42, RECORD_DELIMITER];
    let (env_seed, total_seed) = RawRecordEnvelope::parse(&seed_only, 2).unwrap();
    assert_eq!(total_seed, 5);
    assert_eq!(env_seed.payload, &[0x42]);
    let err = env_seed.decode_payload(8).unwrap_err();
    assert_eq!(
        err,
        FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1
        }
    );
}

#[test]
fn test_trailing_padding_handling() {
    let caps = classify_version(7).unwrap();

    // 1 valid record followed by 1 trailing padding byte (0x00)
    let mut stream = vec![0x01, 0x02, 0x00, 0x42, 0x99, RECORD_DELIMITER];
    stream.push(0x00); // trailing padding byte

    let mut iter = RecordEnvelopeIterator::from_slice(&stream, caps);
    let rec = iter.next().unwrap().expect("Valid record");
    assert_eq!(rec.record_type, 1);
    // Trailing 1 byte cannot form header (requires 3 bytes for v7) -> cleanly returns None
    assert!(iter.next().is_none());

    // 2 trailing padding bytes
    stream.push(0xFF);
    let mut iter2 = RecordEnvelopeIterator::from_slice(&stream, caps);
    let rec2 = iter2.next().unwrap().expect("Valid record");
    assert_eq!(rec2.record_type, 1);
    assert!(iter2.next().is_none());
}

#[test]
fn test_zero_allocation_decode_into_verification() {
    // Stack-allocated scratch buffer
    let mut scratch = [0u8; 64];

    // 1. v1-v6 plaintext into scratch
    let v3_wire = [0x02, 0x04, 0xAA, 0xBB, 0xCC, 0xDD, RECORD_DELIMITER];
    let (env_v3, _) = RawRecordEnvelope::parse(&v3_wire, 1).unwrap();
    let decoded_v3 = env_v3.decode_into(3, &mut scratch).unwrap();
    assert_eq!(decoded_v3, &[0xAA, 0xBB, 0xCC, 0xDD]);

    // 2. v7-v12 XOR into scratch
    // OSD Type 1, seed 42, plaintext [1, 2, 3]
    let key = derive_key(1, 42);
    let c1 = 1 ^ key[0];
    let c2 = 2 ^ key[1];
    let c3 = 3 ^ key[2];
    let v8_wire = [
        0x01,
        0x04,
        0x00,
        42,
        c1,
        c2,
        c3,
        RECORD_DELIMITER,
    ];
    let (env_v8, _) = RawRecordEnvelope::parse(&v8_wire, 2).unwrap();
    let decoded_v8 = env_v8.decode_into(8, &mut scratch).unwrap();
    assert_eq!(decoded_v8, &[1, 2, 3]);

    // 3. BufferOverflow check
    let mut tiny_buf = [0u8; 2];
    let err = env_v8.decode_into(8, &mut tiny_buf).unwrap_err();
    assert_eq!(
        err,
        FlightReaderError::BufferOverflow {
            required: 3,
            capacity: 2
        }
    );
}

#[test]
fn test_record_payload_deref_and_conversions() {
    let slice_data = [10u8, 20, 30];
    let borrowed: RecordPayload = (&slice_data[..]).into();
    assert!(borrowed.is_borrowed());
    assert!(!borrowed.is_owned());
    assert_eq!(borrowed.as_slice(), &[10, 20, 30]);
    assert_eq!(&borrowed[..2], &[10, 20]); // Deref test

    let vec_data = vec![40u8, 50, 60];
    let owned: RecordPayload = vec_data.into();
    assert!(owned.is_owned());
    assert!(!owned.is_borrowed());
    assert_eq!(owned.as_slice(), &[40, 50, 60]);
    assert_eq!(owned.to_vec(), vec![40, 50, 60]);

    // Cow conversion
    let cow_b: std::borrow::Cow<[u8]> = borrowed.into();
    assert!(matches!(cow_b, std::borrow::Cow::Borrowed(_)));

    let cow_o: std::borrow::Cow<[u8]> = owned.into();
    assert!(matches!(cow_o, std::borrow::Cow::Owned(_)));
}

// Proptest Property-based invariant verification
proptest! {
    #![proptest_config(ProptestConfig::with_cases(500))]

    #[test]
    fn prop_raw_record_envelope_parse_never_panics(
        data in prop::collection::vec(any::<u8>(), 0..256),
        width in 1usize..=2,
    ) {
        let _ = RawRecordEnvelope::parse(&data, width);
    }

    #[test]
    fn prop_record_envelope_iterator_never_panics_or_hangs(
        data in prop::collection::vec(any::<u8>(), 0..512),
        version in 1u8..=14,
        resync in any::<bool>(),
    ) {
        let caps = classify_version(version).unwrap();
        let mut iter = RecordEnvelopeIterator::from_slice(&data, caps).with_resync(resync);

        let mut count = 0;
        let mut prev_offset = 0;

        while let Some(item) = iter.next() {
            count += 1;
            // Cursor must monotonically advance
            assert!(iter.current_offset() >= prev_offset);
            prev_offset = iter.current_offset();

            if let Ok(env) = item {
                // If valid envelope, test decode_payload and decode_into
                let _ = env.decode_payload(version);
                let mut scratch = [0u8; 512];
                let _ = env.decode_into(version, &mut scratch);
            }

            // Execution steps must be strictly bounded by input length
            assert!(count <= data.len() + 10);
        }
    }
}

